CREATE FUNCTION public.record_consumer_choice() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'consumer') ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.record_consumer_choice() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_consumer_choice() TO authenticated;
CREATE FUNCTION public.validate_clinician_checkin() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE concern_value text; metric text; value jsonb; allowed text[]; BEGIN SELECT concern INTO concern_value FROM public.clinician_patients WHERE id=NEW.patient_id; allowed=CASE concern_value WHEN 'Rosacea' THEN ARRAY['Redness','Flushing episodes','Burning or stinging','Dryness','Skin sensitivity'] WHEN 'Acne' THEN ARRAY['Breakouts','Irritation','Dryness','Treatment adherence'] WHEN 'Post-procedure' THEN ARRAY['Discomfort','Redness','Dryness'] ELSE ARRAY['Discomfort','Dryness','Sensitivity'] END; IF jsonb_typeof(NEW.ratings)<>'object' OR NEW.ratings='{}'::jsonb THEN RAISE EXCEPTION 'Subjective ratings required'; END IF; FOR metric,value IN SELECT * FROM jsonb_each(NEW.ratings) LOOP IF NOT metric=ANY(allowed) OR jsonb_typeof(value)<>'number' THEN RAISE EXCEPTION 'Invalid subjective metric'; END IF; IF (value::text)::numeric < 0 OR (value::text)::numeric > 4 OR (value::text)::numeric <> trunc((value::text)::numeric) THEN RAISE EXCEPTION 'Subjective rating must be 0 to 4'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER validate_clinician_checkin BEFORE INSERT OR UPDATE ON public.clinician_checkins FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_checkin();
CREATE FUNCTION public.validate_clinician_treatment_dates() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.end_date IS NOT NULL AND NEW.end_date < NEW.start_date THEN RAISE EXCEPTION 'End date precedes start date'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_clinician_treatment_dates BEFORE INSERT OR UPDATE ON public.clinician_treatments FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_treatment_dates();